<?php
declare(strict_types=1);
require_once __DIR__.'/MailSettings.php';
require_once __DIR__.'/SmtpTransport.php';
final class StayMail
{
    public function __construct(private PDO $db,private string $directory,private array $config,private ?SmtpTransport $transport=null){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    public static function enqueue(PDO $db,string $id,string $event,int $version):void{if(!$db->inTransaction())throw new LogicException('Mail enqueue requires a transaction.');$s=$db->prepare("INSERT INTO jingo_stay_mail(id,booking_id,event,last_error) VALUES (?,?,?,'') ON DUPLICATE KEY UPDATE id=id");$s->execute([$id.':'.$version.':'.$event,$id,$event]);}
    private static function uuid(mixed $id):string{if(!is_string($id)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$id))throw new HttpError(400,'Mã yêu cầu không hợp lệ.');return strtolower($id);}
    private function tx(callable $fn):array{$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$out=$fn();$this->db->commit();return $out;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
    private function audit(string $actor,string $action,string $id):void{$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,$action,$id]);}
    public function resend(string $id,array $input,string $actor):array
    {
        $id=self::uuid($id);if(count($input)!==1)throw new HttpError(400,'Yêu cầu gửi lại không hợp lệ.');$request=self::uuid($input['requestId']??null);
        return $this->tx(function()use($id,$request,$actor){if(!$this->query('SELECT id FROM jingo_stay_bookings WHERE id=?',[$id])->fetchColumn())throw new HttpError(404,'Không tìm thấy đơn phòng.');$key='RESEND:'.$request;$prior=$this->query('SELECT booking_id FROM jingo_stay_mail WHERE id=?',[$key])->fetchColumn();if($prior!==false){if($prior!==$id)throw new HttpError(409,'Mã yêu cầu đã dùng cho đơn khác.');return ['ok'=>true];}$this->query("INSERT INTO jingo_stay_mail(id,booking_id,event,last_error) VALUES (?,?,'STATUS','')",[$key,$id]);$this->audit($actor,'stay.mail.resend',$id);return ['ok'=>true];});
    }
    public function retry(string $id,array $input,string $actor):array
    {
        $id=self::uuid($id);if(count($input)!==1||!is_string($input['jobId']??null)||strlen($input['jobId'])>190)throw new HttpError(400,'Email không hợp lệ.');
        return $this->tx(function()use($id,$input,$actor){$job=$this->query('SELECT status FROM jingo_stay_mail WHERE id=? AND booking_id=? FOR UPDATE',[$input['jobId'],$id])->fetchColumn();if($job===false)throw new HttpError(404,'Không tìm thấy email trong đơn.');if($job!=='FAILED')throw new HttpError(409,'Chỉ thử lại email đã thất bại.');if(!(new MailSettings($this->db,$this->directory))->read()['enabled'])throw new HttpError(409,'Bật SMTP trước khi thử lại.');$this->query("UPDATE jingo_stay_mail SET status='PENDING',attempts=0,next_at=UTC_TIMESTAMP(6),last_error='' WHERE id=?",[$input['jobId']]);$this->audit($actor,'stay.mail.retry',$id);return ['ok'=>true];});
    }
    public function journal(array $in):array
    {
        if(array_diff(array_keys($in),['q','status','page'])||array_key_exists('q',$in)&&!is_string($in['q'])||array_key_exists('status',$in)&&!in_array($in['status'],['PENDING','SENDING','SENT','FAILED'],true)||array_key_exists('page',$in)&&(!is_string($in['page'])&&!is_int($in['page'])||!preg_match('/^[1-9][0-9]{0,5}$/D',(string)$in['page'])))throw new HttpError(400,'Bộ lọc email không hợp lệ.');$q=trim($in['q']??'');if(mb_strlen($q,'UTF-8')>120)throw new HttpError(400,'Từ khóa quá dài.');
        return $this->tx(function()use($in,$q){$where=[];$args=[];if(isset($in['status'])){$where[]='m.status=?';$args[]=$in['status'];}if($q!==''){$where[]='LOCATE(LOWER(?),LOWER(b.code))>0';$args[]=$q;}$sql=' FROM jingo_stay_mail m JOIN jingo_stay_bookings b ON b.id=m.booking_id'.($where?' WHERE '.implode(' AND ',$where):'');$total=(int)$this->query('SELECT COUNT(*)'.$sql,$args)->fetchColumn();$page=min((int)($in['page']??1),max(1,(int)ceil($total/25)));$rows=$this->query('SELECT m.id,m.booking_id,b.code,m.event,m.status,m.attempts,m.next_at,m.last_error,m.created_at,m.sent_at'.$sql.' ORDER BY m.created_at DESC,m.id DESC LIMIT 25 OFFSET '.(($page-1)*25),$args)->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['attempts']=(int)$r['attempts'];if($r['last_error']!=='')$r['last_error']='SMTP gửi thất bại; kiểm tra cấu hình, khóa mã hóa và URL website.';}unset($r);return ['data'=>$rows,'total'=>$total,'page'=>$page,'pageSize'=>25];});
    }
    private function message(array $job,array $row):array
    {
        $d=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);$en=$d['locale']==='en';$states=$en?['PENDING'=>'Awaiting property confirmation','CONFIRMED'=>'Confirmed','CHECKED_IN'=>'Checked in','COMPLETED'=>'Completed','CANCELLED'=>'Cancelled','EXPIRED'=>'Hold expired']:['PENDING'=>'Chờ cơ sở xác nhận','CONFIRMED'=>'Đã xác nhận','CHECKED_IN'=>'Đã nhận phòng','COMPLETED'=>'Hoàn tất','CANCELLED'=>'Đã hủy','EXPIRED'=>'Hết hạn giữ phòng'];$event=$job['event'];if(in_array($event,['CONFIRMED','CHECKED_IN','COMPLETED','CANCELLED','EXPIRED'],true)&&$event!==$row['status'])$event='STATUS';$titles=$en?['CREATED'=>'Stay booking received','PAID'=>'Stay payment recorded','CONFIRMED'=>'Stay booking confirmed','CANCELLED'=>'Stay booking cancelled']:['CREATED'=>'Đã nhận đơn đặt phòng','PAID'=>'Đã ghi nhận thanh toán phòng','CONFIRMED'=>'Đã xác nhận đặt phòng','CANCELLED'=>'Đơn phòng đã hủy'];$title=$titles[$event]??($en?'Stay booking update':'Cập nhật đơn đặt phòng');
        $base=$this->config['PUBLIC_BASE_URL']??'';$u=parse_url($base);if(!$u||!isset($u['host'],$u['scheme'])||isset($u['user'])||isset($u['pass'])||isset($u['query'])||isset($u['fragment'])||!in_array($u['scheme'],['http','https'],true)||($this->config['APP_ENV']??'production')!=='development'&&$u['scheme']!=='https')throw new RuntimeException('Invalid website URL.');$origin=$u['scheme'].'://'.$u['host'].(isset($u['port'])?':'.$u['port']:'');$key=(new SecretCipher($this->directory))->decrypt($row['secret']);if(!preg_match('/^[a-f0-9]{64}$/D',$key))throw new RuntimeException('Invalid booking key.');$link=$origin.($en?'/en/stays/booking':'/dat-phong/tra-cuu').'#'.$row['code'].':'.$key;
        $lines=[$title,$row['code'],$d['hotelName'],$d['roomName'],$d['address'],$d['checkIn'].' → '.$d['checkOut'].' · '.$row['rooms'].($en?' room(s)':' phòng'),($en?'Check-in / check-out time: ':'Giờ nhận / trả: ').$d['checkInTime'].' / '.$d['checkOutTime'],($en?'Total: ':'Tổng tiền: ').number_format($d['total'],0,',','.').' VND',($en?'Booking: ':'Trạng thái đơn: ').($states[$row['status']]??$row['status']),($en?'Payment: ':'Thanh toán: ').($d['paymentStatus']==='PAID'?($en?'Paid':'Đã thu tiền'):($en?'Unpaid':'Chưa thu tiền'))];
        if(isset($d['manualPreference'])){$m=$d['manualPreference'];$lines[]=$en?($m['englishName']?:$m['name']):$m['name'];$lines[]=$en?($m['englishInstructions']?:$m['instructions']):$m['instructions'];}$lines[]=$d['policy'];$lines[]=$en?'Receipt, property confirmation and payment are separate. Check the current status using your private link.':'Tiếp nhận đơn, xác nhận cơ sở và thu tiền là các trạng thái riêng. Xem trạng thái mới nhất tại liên kết riêng.';$lines[]=$link;$lines[]=$en?'Keep this link private.':'Giữ kín liên kết này.';
        return [$d['contact']['email'],$title.' · '.$row['code'],implode("\n\n",array_filter($lines,fn($v)=>$v!==''))];
    }
    public function processOne():string
    {
        $c=(new MailSettings($this->db,$this->directory))->credentials();if(!$c)return 'disabled';$lock='jm-mail-'.substr(hash('sha256',(string)$this->query('SELECT DATABASE()')->fetchColumn()),0,40);if((int)$this->query('SELECT GET_LOCK(?,0)',[$lock])->fetchColumn()!==1)return 'busy';
        try{
            $this->db->beginTransaction();try{$job=$this->query("SELECT * FROM jingo_stay_mail WHERE status IN ('PENDING','SENDING') AND next_at<=UTC_TIMESTAMP(6) ORDER BY created_at,id LIMIT 1 FOR UPDATE")->fetch(PDO::FETCH_ASSOC);if(!$job){$this->db->commit();return 'empty';}if((int)$job['attempts']>=5){$this->query("UPDATE jingo_stay_mail SET status='FAILED',last_error=? WHERE id=?",['Đã hết số lần thử; kiểm tra người nhận trước khi gửi lại.',$job['id']]);$this->db->commit();return 'failed';}$attempt=(int)$job['attempts']+1;$this->query("UPDATE jingo_stay_mail SET status='SENDING',attempts=?,next_at=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 120 SECOND) WHERE id=?",[$attempt,$job['id']]);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
            try{
                $row=$this->tx(function()use($job){$this->query("UPDATE jingo_stay_bookings SET status='EXPIRED',version=version+1 WHERE id=? AND status='PENDING' AND expires_at<=UTC_TIMESTAMP(6) AND JSON_UNQUOTE(JSON_EXTRACT(data,'$.paymentStatus'))='UNPAID'",[$job['booking_id']]);return $this->query('SELECT code,status,data,secret,rooms FROM jingo_stay_bookings WHERE id=?',[$job['booking_id']])->fetch(PDO::FETCH_ASSOC)?:throw new RuntimeException('Missing booking.');});
                [$to,$subject,$text]=$this->message($job,$row);($this->transport??new SmtpTransport())->send($c,$to,$subject,$text,$job['id']);$this->query("UPDATE jingo_stay_mail SET status='SENT',sent_at=UTC_TIMESTAMP(6),last_error='' WHERE id=? AND status='SENDING' AND attempts=?",[$job['id'],$attempt]);return 'sent';
            }catch(Throwable){$state=$attempt>=5?'FAILED':'PENDING';$delay=60*(2**min($attempt-1,6));$this->query("UPDATE jingo_stay_mail SET status=?,last_error=?,next_at=DATE_ADD(UTC_TIMESTAMP(6),INTERVAL ".$delay." SECOND) WHERE id=? AND status='SENDING' AND attempts=?",[$state,'SMTP gửi thất bại; kiểm tra cấu hình và gửi lại từ đơn phòng.',$job['id'],$attempt]);return strtolower($state);}
        }finally{$this->query('SELECT RELEASE_LOCK(?)',[$lock]);}
    }
}
